const users = [
  { name: "Аня", age: 20 },
  { name: "Боря", age: 17 },
  { name: "Кира", age: 22 },
];

const names = users.map((u) => u.name);
const adults = users.filter((u) => u.age >= 18);
const totalAge = users.reduce((sum, u) => sum + u.age, 0);

console.log(names);
console.log(adults);
console.log(totalAge);
